-- Rifts World Book 17: Warlords of Russia, batch 2b: body armor, horse
-- barding and the two bionic horses. 13 new gear rows from printed 171-176.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-warlords-of-russia-armor.sql
--
-- ALL 13 ARE NEW - catalog-diff --table gear --remote and a slug query,
-- 2026-10-01.
--
-- THE BIONIC HORSES ARE GEAR ROWS, category 'vehicle', ON NATE'S WORD
-- (survey decision D3, 2026-10-01). New West's robot horses are rows in the
-- vehicles table; these are not, by decision, and their M.D.C. by location is
-- in the description, the way the Lone Star DPM armors carry theirs.
--
-- A RANGE STORES ITS LOW END, with the full range in cost_note or the
-- description (gear.cost in db/schema.sql). Homemade armor prints one cost
-- range and one weight range for both grades; it is two rows because the
-- M.D.C. differs. Cyborg Battle Armor prints three grades with their own
-- M.D.C., weight and price, and is three rows.
--
-- PRINTED 175 SETS THE BEAR'S AND THE LYNX'S LAST LINES SIDE BY SIDE, and the
-- cache returns them run together. Assigned off a render: the exoskeleton,
-- the height, the -30% penalty and 75,000 credits are the Bear's; 26,000
-- credits and excellent availability are the Lynx's.
--
-- THE DIGIT CIPHER lands on the Type One horse's back leg kick (1D6x10+15)
-- and the Type Two's stomp (2D6x10). Read as the dice they can only be.
--
-- NOT HERE: the MM-61 Explorer Exoframe (printed 176-177) has its own
-- M.D.C. by location, speed and tool arms and ships with the vehicles and
-- power armor batch.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('homemade-mdc-armor-light', 'Homemade M.D.C. Armor (Light)', 'rifts', 'armor', 25, 8000, '8,000-12,000 credits, light or medium; the low end is stored. Good availability even in wilderness regions.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 30, 'Piecemeal "hodgepodge" armor of M.D.C. hide and bone with salvaged ceramic or alloy plates. Never environmental. M.D.C. 30-45 for light armor (the low end is stored); weight 25-35 pounds. Fair mobility: -10% to prowl, climb, swim, acrobatics and gymnastics. Heavy armor is not possible.', 'Rifts World Book 17: Warlords of Russia p.173'),
('homemade-mdc-armor-medium', 'Homemade M.D.C. Armor (Medium)', 'rifts', 'armor', 25, 8000, '8,000-12,000 credits, light or medium; the low end is stored. Good availability even in wilderness regions.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 50, 'Piecemeal "hodgepodge" armor of M.D.C. hide and bone with salvaged ceramic or alloy plates. Never environmental. M.D.C. 50-65 for medium armor (the low end is stored); weight 25-35 pounds, one range printed for both grades. Fair mobility: -10% to prowl, climb, swim, acrobatics and gymnastics. Heavy armor is not possible.', 'Rifts World Book 17: Warlords of Russia p.173'),
('trapper-body-armor', 'Trapper Body Armor', 'rifts', 'armor', 10, 12000, '12,000 credits. Excellent availability.', '2D4 M.D. each (retractable forearm Vibro-Blades)', 1, NULL, NULL, NULL, NULL, NULL, 45, 'A light, non-environmental suit of quilted armor with chest, forearm, thigh and lower leg plates, worn by hunters, trappers and loggers and popular in the War Camps. Each forearm vambrace holds a retractable Vibro-Blade. Superior mobility, no penalties.', 'Rifts World Book 17: Warlords of Russia p.173'),
('sovietski-red-star-medium-body-armor', 'Sovietski "Red Star" Medium Body Armor', 'rifts', 'armor', 18, 28000, 'Black Market 28,000-32,000 credits for the bootleg copy; the low end is stored. Good availability outside the Sovietski, where the bootleg is illegal (remove it and pay a 500 credit fine, or leave).', NULL, 0, NULL, NULL, NULL, NULL, NULL, 75, 'The armor of non-cyborg Sovietski troops and police: grey super-ceramic plates over deep red padding, with a removable one-way mirrored face plate and no spikes. The bootleg puts the spikes back and swaps the Red Star for a skull. Good mobility: -10% to prowl, climb, swim, acrobatics and gymnastics. Never worn in a War Camp except as a disguise.', 'Rifts World Book 17: Warlords of Russia p.173'),
('battleforge-body-armor', 'Battleforge Body Armor', 'rifts', 'armor', 25, 27000, '27,000-30,000 credits; the low end is stored. A retractable forearm Vibro-Blade is 6,000 credits extra. Good availability in Warlord-held Western Russia, fair in wilderness regions, Mongolia, Poland and Romania.', '1D6 or 2D4 M.D. (optional retractable forearm Vibro-Blade)', 1, NULL, NULL, NULL, NULL, NULL, 90, 'Heavy environmental armor of lightweight ceramic and composite, popular with Warlord troops, mercenaries and adventurers. Main body 90 M.D.C., helmet 60. Each forearm has a shallow storage compartment, and the back plate has modular clamps for a jet pack, power pack or ammo-drum. Fair mobility: -20% to prowl, climb, swim, acrobatics and gymnastics. Full environmental armor with the standard Russian features (printed 173).', 'Rifts World Book 17: Warlords of Russia p.174'),
('bear-body-armor', 'Bear Body Armor', 'rifts', 'armor', 160, 75000, 'Black Market cost 75,000 credits. Fair availability.', '1D4 M.D. restrained punch, 1D6 M.D. full strength punch or kick, 2D6 M.D. power punch (two attacks)', 1, NULL, NULL, NULL, NULL, NULL, 150, 'A big, bulky full environmental suit with a reinforced exoskeleton, in effect light power armor: robot P.S. 26, lifts and carries up to 1,200 pounds, and stands 1-2 feet taller than its wearer. Main body 150 M.D.C., helmet 70. Best suited to Light Machines, partial cyborgs and the very strong. Heated to tolerate -100 Centigrade. Poor to fair mobility: -30% to prowl, climb, swim, acrobatics and gymnastics.', 'Rifts World Book 17: Warlords of Russia p.174-175'),
('lynx-body-armor', 'Lynx Body Armor', 'rifts', 'armor', 17, 26000, 'Black Market cost 26,000 credits. Excellent availability.', '2D6 M.D. single large Vibro-Blade, 4D6 M.D. a pair; +1 to parry', 1, NULL, NULL, NULL, NULL, NULL, 60, 'A fully environmental suit with a feline helmet whose ear-like guards hold a sound amplification system (as bionic amplified hearing), and a pair of long, curved retractable Vibro-Blades on each forearm. A Kolodenko War Camp design, widely copied. Main body 60 M.D.C., helmet 40. Slots and connectors for hooking on gear. Excellent mobility: -5% to prowl, climb, swim, acrobatics and gymnastics.', 'Rifts World Book 17: Warlords of Russia p.175'),
('cyborg-battle-armor-light', 'Cyborg Battle Armor (Light)', 'rifts', 'armor', 100, 45000, 'Black Market cost 45,000 credits. Good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 140, 'Dense body armor for Light and Heavy Machines of humanoid build, worn over the bionic frame. Main body 140 M.D.C., helmet 50. Non-environmental. Fair to poor mobility: -10% to prowl, climb, swim, acrobatics and gymnastics.', 'Rifts World Book 17: Warlords of Russia p.175-176'),
('cyborg-battle-armor-medium', 'Cyborg Battle Armor (Medium)', 'rifts', 'armor', 200, 70000, 'Black Market cost 70,000 credits. Good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 180, 'Dense body armor for Light and Heavy Machines of humanoid build, worn over the bionic frame. Main body 180 M.D.C., helmet 65. Non-environmental. Fair to poor mobility: -10% to prowl, climb, swim, acrobatics and gymnastics.', 'Rifts World Book 17: Warlords of Russia p.175-176'),
('cyborg-battle-armor-heavy', 'Cyborg Battle Armor (Heavy)', 'rifts', 'armor', 300, 120000, 'Black Market cost 120,000 credits. Good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 280, 'Dense body armor for Light and Heavy Machines of humanoid build, worn over the bionic frame. Main body 280 M.D.C., helmet 80. Non-environmental. Fair to poor mobility: -20% to prowl, climb, swim, acrobatics and gymnastics.', 'Rifts World Book 17: Warlords of Russia p.175-176'),
('horse-barding', 'Horse Barding', 'rifts', 'armor', 100, 24000, 'Market cost 24,000 credits; sometimes 10-30% less in a sale or when used or stolen. Warlord cost 6,000.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 140, 'Non-environmental body armor for a real horse with no bionics. Armor Rating 18: a higher roll penetrates and can kill the horse. M.D.C. by location: front legs 40 each, rear legs 60 each, chest 90, head and neck 100, main body 140. Running speed down 5% (about 32 mph), leaps down 10%, fatigue unchanged. The usual -3 and -7 penalties to strike a moving horse apply.', 'Rifts World Book 17: Warlords of Russia p.172'),
('type-one-partial-bionic-horse', 'Type One Partial Bionic Horse', 'rifts', 'vehicle', 800, 1500000, 'Market cost 1.5 million credits; sometimes 10-30% less in a sale or when stolen. Add 80,000 for a bionic lung, 100,000 for bionic augmented hearing and 300,000 for a bionic heart. Warlord cost around 250,000 to 350,000.', 'Stomp 3D6+15 S.D.C.; front leg kick 5D6+15 S.D.C.; back leg kick 1D6x10+15 S.D.C.; hind leg power kick 1D6 M.D. (two of the animals attacks)', 1, NULL, NULL, NULL, NULL, NULL, 150, 'A horse whose four legs, hips and chest are bionic; body armor protects the head, neck and upper body. M.D.C. by location: front legs 90 each, rear legs 120 each, chest 110, head and neck armor 100, main body armor 150. Runs 40 mph, leaps 10% farther, fatigue down 40%, P.S. about a human 35 (pulls two tons). +1 initiative, +1 to dodge when running, +1 to roll with impact. Loses a third of its P.P.E. and of its sensitivity to the supernatural. Attackers are usually -3 to strike a moving horse or rider (marksmen such as Cossacks excepted); the legs and the head and neck armor are a further -4.', 'Rifts World Book 17: Warlords of Russia p.171-172'),
('type-two-full-conversion-bionic-horse', 'Type Two Full Conversion Bionic Horse', 'rifts', 'vehicle', 1400, 3600000, 'Market cost 3.6 million credits; sometimes 10-20% less in a sale or when used or stolen. Warlord cost one million.', 'Stomp 2D6x10 S.D.C. or one M.D.; front leg kick 1D4 M.D.; back leg kick 2D4 M.D.; hind leg power kick 2D6+4 M.D. (two of the animals attacks)', 1, NULL, NULL, NULL, NULL, NULL, 275, 'A mechanical body with the head or brain of a real horse, which keeps its behavior and personality. M.D.C. by location: front legs 125 each, rear legs 180 each, chest 160, head and neck 140, main body 275. Runs 60 mph, leaps 12 feet high and 24 long with a running start, fatigue down 90%, robot P.S. 26 (pulls six tons). +3 initiative, +3 to dodge when running, +2 to roll with impact, +2 to save vs Horror Factor. Loses half its P.P.E. and all sensitivity to the supernatural. Attackers are usually -3 to strike a moving horse or rider (marksmen such as Cossacks excepted); the legs are a further -4.', 'Rifts World Book 17: Warlords of Russia p.172');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 13 Warlords of Russia armor and mount rows are in' AS assertion, count(*) AS got, 13 AS want
  FROM gear WHERE slug IN ('homemade-mdc-armor-light', 'homemade-mdc-armor-medium', 'trapper-body-armor', 'sovietski-red-star-medium-body-armor', 'battleforge-body-armor', 'bear-body-armor', 'lynx-body-armor', 'cyborg-battle-armor-light', 'cyborg-battle-armor-medium', 'cyborg-battle-armor-heavy', 'horse-barding', 'type-one-partial-bionic-horse', 'type-two-full-conversion-bionic-horse');
SELECT 'and every one cites Warlords of Russia' AS assertion, count(*) AS got, 13 AS want
  FROM gear WHERE source_book LIKE 'Rifts World Book 17: Warlords of Russia p.%' AND slug IN ('homemade-mdc-armor-light', 'homemade-mdc-armor-medium', 'trapper-body-armor', 'sovietski-red-star-medium-body-armor', 'battleforge-body-armor', 'bear-body-armor', 'lynx-body-armor', 'cyborg-battle-armor-light', 'cyborg-battle-armor-medium', 'cyborg-battle-armor-heavy', 'horse-barding', 'type-one-partial-bionic-horse', 'type-two-full-conversion-bionic-horse');
SELECT 'the two bionic horses are gear rows in category vehicle' AS assertion, count(*) AS got, 2 AS want
  FROM gear WHERE slug IN ('type-one-partial-bionic-horse', 'type-two-full-conversion-bionic-horse') AND category = 'vehicle';
SELECT 'the Bear and the Lynx kept their own figures' AS assertion, count(*) AS got, 2 AS want
  FROM gear WHERE (slug = 'bear-body-armor' AND mdc = 150 AND cost = 75000 AND weight_lbs = 160) OR (slug = 'lynx-body-armor' AND mdc = 60 AND cost = 26000 AND weight_lbs = 17);

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-warlords-of-russia-armor.sql');
